//! The bundled `srd-5.1-rules-text` and `srd-5.2.1-rules-text` packs (`borealis-docs/1`): schema validity,
//! page and path on every section, unique ids, the required CC-BY-4.0 attribution, and spot checks against the
//! printed SRD pages. The packs are generated by `content-tools/rules-text/build.py` (see their COVERAGE.md).

use borealis_content::schema::validate_docs;
use serde_json::Value;
use std::collections::BTreeSet;
use std::fs;
use std::path::{Path, PathBuf};

const SEP: &str = " > ";
/// Share of sections that must carry text (a few headings are followed directly by sub-headings).
const MIN_SECTIONS_WITH_TEXT_PERCENT: usize = 95;

fn pack_dir(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../content")
        .join(name)
}

fn load(name: &str) -> Value {
    let text = fs::read_to_string(pack_dir(name).join("docs.json")).expect("docs.json");
    serde_json::from_str(&text).expect("docs.json is JSON")
}

fn sections(doc: &Value) -> &Vec<Value> {
    doc["sections"].as_array().expect("sections")
}

fn path_of(section: &Value) -> String {
    section["path"]
        .as_array()
        .unwrap()
        .iter()
        .map(|p| p.as_str().unwrap())
        .collect::<Vec<_>>()
        .join(SEP)
}

fn find<'a>(doc: &'a Value, path: &str) -> &'a Value {
    sections(doc)
        .iter()
        .find(|s| path_of(s) == path)
        .unwrap_or_else(|| panic!("section {path} not found"))
}

fn check_pack(name: &str, ruleset: &str, last_pdf_page: u64, attribution_start: &str) -> Value {
    let doc = load(name);
    let violations = validate_docs(&doc).unwrap();
    assert!(violations.is_empty(), "{name}: {violations:?}");
    assert_eq!(doc["ruleset"], ruleset);
    assert_eq!(doc["info"]["id"], name);
    assert_eq!(doc["info"]["license"], "CC-BY-4.0");
    let attribution = doc["info"]["attribution"].as_str().unwrap();
    assert!(attribution.starts_with(attribution_start), "{name}");
    assert!(attribution.contains("https://creativecommons.org/licenses/by/4.0/legalcode"));

    let text = fs::read_to_string(pack_dir(name).join("ATTRIBUTION.md")).unwrap();
    assert!(text.contains(&attribution[..attribution.find(" Modified:").unwrap()]));
    assert!(pack_dir(name).join("COVERAGE.md").exists());
    // Not an element pack: it must never be picked up by the content store.
    assert!(!pack_dir(name).join("pack.json").exists());

    let mut ids = BTreeSet::new();
    let mut paths = BTreeSet::new();
    for s in sections(&doc) {
        let path = path_of(s);
        let page = s["page"].as_u64().unwrap();
        assert!((1..=last_pdf_page).contains(&page), "{path}: page {page}");
        assert!(ids.insert(s["id"].as_str().unwrap()), "duplicate id {path}");
        assert!(paths.insert(path.clone()), "duplicate path {path}");
        let html = s["html"].as_str().unwrap();
        assert!(
            !html.contains('\u{2011}'),
            "{path}: internal hyphen marker leaked"
        );
        assert!(!html.contains("  "), "{path}: unnormalised whitespace");
    }
    let with_text = sections(&doc)
        .iter()
        .filter(|s| !s["html"].as_str().unwrap().is_empty())
        .count();
    assert!(
        with_text * 100 >= sections(&doc).len() * MIN_SECTIONS_WITH_TEXT_PERCENT,
        "{name}: too many empty sections"
    );
    doc
}

#[test]
fn srd521_rules_text_pack() {
    let doc = check_pack(
        "srd-5.2.1-rules-text",
        "dnd2024",
        364,
        "This work includes material from the System Reference Document 5.2.1",
    );
    assert!(sections(&doc).len() >= 600);
    let cover = find(&doc, "Playing the Game > Combat > Cover");
    assert_eq!(cover["page"], 15);
    assert!(cover["html"]
        .as_str()
        .unwrap()
        .contains("Three-Quarters Cover"));
    // Every glossary entry is its own section, including the ones the typed pack lacks.
    let hp = find(&doc, "Rules Glossary > Hit Points");
    assert_eq!(hp["page"], 183);
    let glossary = sections(&doc)
        .iter()
        .filter(|s| path_of(s).starts_with("Rules Glossary > "))
        .count();
    assert!(glossary >= 150, "glossary entries: {glossary}");
    // Element chapters are out of scope.
    assert!(sections(&doc)
        .iter()
        .all(|s| !path_of(s).starts_with("Classes") && !path_of(s).starts_with("Monsters A")));
}

#[test]
fn srd51_rules_text_pack() {
    let doc = check_pack(
        "srd-5.1-rules-text",
        "dnd2014",
        403,
        "This work includes material taken from the System Reference Document 5.1",
    );
    assert!(sections(&doc).len() >= 250);
    let dodge = find(&doc, "Combat > Actions in Combat > Dodge");
    assert_eq!(dodge["page"], 93);
    assert!(dodge["html"].as_str().unwrap().contains("Dodge action"));
    find(&doc, "Adventuring > Resting");
    find(&doc, "Gamemastering > Traps");
    find(&doc, "Spellcasting > Casting a Spell > Components");
}
